package __PACKAGE__;

import net.fabricmc.api.ModInitializer;
import net.minecraft.core.Registry;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.ResourceLocation;

/**
 * Registers the particle type of Sparkle ("__MODID__:sparkle"). An entry point of "main" in fabric.mod.json, next to
 * the one of the mod: the plugin adds it there.
 * Generated by the Sparkle plugin: do not edit, it is written again when the runtime is updated.
 */
public final class SparkleFabric implements ModInitializer {
    @Override
    public void onInitialize() {
        Registry.register(BuiltInRegistries.PARTICLE_TYPE, ResourceLocation.tryParse(SparkleConfig.MOD_ID + ":" + Sparkle.TYPE_NAME), Sparkle.TYPE);
    }
}
